1	//! The checker a run asks, and the one place that picks which: the `tsrs` crates linked into this process, or a
2	//! `tsc --api` process when an explicit `tsc_path` names one (the Go `typescript@7.1` the tests and the parity gate
3	//! run, or a `tsrs` binary). Both answer the same methods with the same JSON, so [`crate::rpc`] does not know which.
4	//!
5	//! The linked checker answers on threads of its own with a 512 MiB stack, the stack the `tsrs` binary serves on. A
6	//! query runs on the thread that calls it, and a type nested 2,000 deep overflows a default 2 MiB thread: a stack
7	//! overflow aborts the whole process and cannot be caught. Callers on any thread send it requests over a channel, one
8	//! per checker thread (a lane), and each thread answers its own one at a time, in the order they arrive; a run that asks
9	//! several programs at once sends each program's requests down a lane of its own ([`Client::lane`]). A panic inside the
10	//! checker comes back as an error to the request that caused it (`tsrs_api` catches it), and the session keeps
11	//! answering.
12	
13	use std::sync::atomic::{AtomicUsize, Ordering};
14	use std::sync::{Arc, mpsc};
15	use std::thread::JoinHandle;
16	use std::time::Duration;
17	
18	use caliper_docgen_tsc_client::{Supervisor, SupervisorConfig, TscClientError};
19	use camino::Utf8Path;
20	use serde_json::Value;
21	use tokio::sync::oneshot;
22	use tsrs_api::{Handler, Response, Session, SessionOptions};
23	use tsrs_vfs::{FS, bundled, osvfs};
24	
25	use crate::kept::{Reads, Recording};
26	use crate::locate;
27	
28	/// The stack of the thread the linked checker answers on: what the `tsrs` binary gives each of its threads.
29	const CHECKER_STACK_BYTES: usize = 512 << 20;
30	
31	/// The JSON-RPC code the `tsrs` and `tsc` processes answer a failed request with (`jsonrpc.CodeInternalError`); the
32	/// message is the error's text, as here.
33	const INTERNAL_ERROR: i64 = -32603;
34	
35	/// How to start a checker: an explicit binary runs as a process, none links the bundled one.
36	pub(crate) struct Start<'a> {
37	    pub(crate) project_root: &'a Utf8Path,
38	    pub(crate) tsc_path: Option<&'a Utf8Path>,
39	    pub(crate) expected_versions: &'static [&'static str],
40	    pub(crate) timeout: Duration,
41	    pub(crate) extra_env: &'a [(String, String)],
42	    /// How many threads the linked checker answers on: requests about different programs of its session run at once.
43	    /// A process answers on its own terms.
44	    pub(crate) threads: usize,
45	    /// Note every question the linked checker asks of the disk here ([`crate::kept`]); a process's are not seen.
46	    pub(crate) reads: Option<Arc<Reads>>,
47	}
48	
49	/// A running checker.
50	pub(crate) enum Backend {
51	    /// A `tsc --api` process for an explicit binary.
52	    Process(Box<Supervisor>),
53	    /// The checker linked into this process, on its own thread.
54	    InProcess(InProcess),
55	}
56	
57	impl Backend {
58	    /// The checker `start` asks for. An explicit path that does not exist, a binary that does not start or is not a
59	    /// supported version, or a checker thread that cannot be spawned, is an error that says so.
60	    pub(crate) async fn start(start: Start<'_>) -> Result<Backend, String> {
61	        let Some(tsc_path) = start.tsc_path else {
62	            return InProcess::start(start.project_root, start.threads, start.reads).map(Backend::InProcess);
63	        };
64	        let tsc_path = locate::explicit_tsc(tsc_path)?;
65	        let mut config = SupervisorConfig::new(tsc_path, start.project_root.to_owned(), start.expected_versions);
66	        config.handshake_timeout = start.timeout;
67	        config.extra_env = start.extra_env.to_vec();
68	        Supervisor::spawn(config)
69	            .await
70	            .map(|supervisor| Backend::Process(Box::new(supervisor)))
71	            .map_err(|error| error.to_string())
72	    }
73	
74	    /// How many programs a run asks at once: one per thread of the linked checker, one for a process (whose requests
75	    /// this client sends one at a time).
76	    pub(crate) fn parallel_programs(&self) -> usize {
77	        match self {
78	            Backend::Process(_) => 1,
79	            Backend::InProcess(checker) => checker.threads,
80	        }
81	    }
82	
83	    pub(crate) fn client(&self) -> Client {
84	        match self {
85	            Backend::Process(supervisor) => Client::Process(supervisor.client()),
86	            Backend::InProcess(checker) => Client::InProcess(checker.client.clone()),
87	        }
88	    }
89	
90	    pub(crate) fn is_alive(&self) -> bool {
91	        match self {
92	            Backend::Process(supervisor) => supervisor.is_alive(),
93	            Backend::InProcess(checker) => !checker.thread.is_finished(),
94	        }
95	    }
96	
97	    /// The operating system's id of the checker process; `None` for the linked checker, which is this process.
98	    pub(crate) fn process_id(&self) -> Option<u32> {
99	        match self {
100	            Backend::Process(supervisor) => supervisor.process_id(),
101	            Backend::InProcess(_) => None,
102	        }
103	    }
104	
105	    /// Stops the checker. A process is reaped. The linked checker's thread finishes the request it is in, closes its
106	    /// session and exits on its own: it is not waited for, so a hung request cannot hold the caller.
107	    pub(crate) async fn shutdown(self) {
108	        match self {
109	            Backend::Process(supervisor) => {
110	                if let Err(error) = (*supervisor).shutdown().await {
111	                    tracing::debug!(%error, "the checker process did not shut down cleanly");
112	                }
113	            }
114	            Backend::InProcess(checker) => checker.client.stop(),
115	        }
116	    }
117	}
118	
119	/// A handle that sends requests to a running checker. Cheap to clone.
120	#[derive(Clone)]
121	pub(crate) enum Client {
122	    Process(caliper_docgen_tsc_client::Client),
123	    InProcess(Linked),
124	}
125	
126	impl Client {
127	    /// The client whose requests the `lane`th thread of the linked checker answers ([`InProcess::start`]); a process
128	    /// has one lane, so its client is itself.
129	    pub(crate) fn lane(&self, lane: usize) -> Client {
130	        match self {
131	            Client::Process(client) => Client::Process(client.clone()),
132	            Client::InProcess(linked) => Client::InProcess(Linked { lanes: linked.lanes.clone(), lane }),
133	        }
134	    }
135	
136	    /// One request, its answer the `result` as the JSON text it arrived as. The wait is bounded by `deadline`; an
137	    /// error is the one the process route would give for the same failure. The linked checker's text is handed on as
138	    /// it was written, not read through first: the caller parses it once, into the shape it expects.
139	    pub(crate) async fn request_raw(
140	        &self,
141	        method: &str,
142	        params: Value,
143	        deadline: Duration,
144	    ) -> Result<Box<str>, TscClientError> {
145	        match self {
146	            Client::Process(client) => Ok(client.request_raw(method, params, deadline).await?.result.into()),
147	            Client::InProcess(linked) => linked.request(method, params, deadline).await,
148	        }
149	    }
150	}
151	
152	/// The linked checker: the thread that owns its session, and the way to it.
153	pub(crate) struct InProcess {
154	    client: Linked,
155	    thread: JoinHandle<()>,
156	    threads: usize,
157	}
158	
159	enum Job {
160	    Request(Asked),
161	    /// Close the session and end the thread; requests sent after it fail as from a stopped checker.
162	    Stop,
163	}
164	
165	struct Asked {
166	    method: String,
167	    params: Vec<u8>,
168	    reply: oneshot::Sender<Result<String, String>>,
169	}
170	
171	/// The sending ends of the linked checker's queues, one per thread, and the one this client sends to.
172	#[derive(Clone)]
173	pub(crate) struct Linked {
174	    lanes: Arc<[mpsc::Sender<Job>]>,
175	    lane: usize,
176	}
177	
178	impl InProcess {
179	    /// Spawns the checker thread, which creates its session there: the session's work, from the first request on,
180	    /// runs on that thread's stack. With `threads` above one it starts as many more, each answering a queue of its own
181	    /// (a lane, [`Client::lane`]) on the same session: requests about one program wait for each other (each program
182	    /// has one checker, which `tsrs_api` locks for the length of a request), so a run that sends the requests about
183	    /// each of its programs down a lane of its own has them answered at once.
184	    pub(crate) fn start(
185	        project_root: &Utf8Path,
186	        threads: usize,
187	        reads: Option<Arc<Reads>>,
188	    ) -> Result<InProcess, String> {
189	        let (lanes, queues): (Vec<_>, Vec<_>) = (0..threads.max(1)).map(|_| mpsc::channel()).unzip();
190	        let threads = lanes.len();
191	        let cwd = project_root.to_string();
192	        let thread = std::thread::Builder::new()
193	            .name("caliper-checker".to_string())
194	            .stack_size(CHECKER_STACK_BYTES)
195	            .spawn(move || serve(cwd, queues, reads))
196	            .map_err(|error| format!("could not start the checker thread: {error}"))?;
197	        Ok(InProcess { client: Linked { lanes: lanes.into(), lane: 0 }, thread, threads })
198	    }
199	}
200	
201	impl Linked {
202	    async fn request(&self, method: &str, params: Value, deadline: Duration) -> Result<Box<str>, TscClientError> {
203	        let params = serde_json::to_vec(&params).map_err(|error| TscClientError::Serialize(Arc::new(error)))?;
204	        let (reply, answer) = oneshot::channel();
205	        let asked = Asked { method: method.to_string(), params, reply };
206	        let Some(jobs) = self.lanes.get(self.lane % self.lanes.len().max(1)) else {
207	            return Err(TscClientError::SessionClosed);
208	        };
209	        if jobs.send(Job::Request(asked)).is_err() {
210	            return Err(TscClientError::SessionClosed);
211	        }
212	        let answered = match tokio::time::timeout(deadline, answer).await {
213	            Ok(Ok(answered)) => answered,
214	            // The thread ended without answering: stopped, or its session could not be created.
215	            Ok(Err(_dropped)) => return Err(TscClientError::SessionClosed),
216	            Err(_elapsed) => return Err(TscClientError::Timeout { method: method.to_string(), after: deadline }),
217	        };
218	        match answered {
219	            Ok(text) => Ok(text.into_boxed_str()),
220	            Err(message) => Err(TscClientError::RpcError { code: INTERNAL_ERROR, message, data: None }),
221	        }
222	    }
223	
224	    fn stop(&self) {
225	        // A thread that already ended has nothing to stop.
226	        for jobs in self.lanes.iter() {
227	            jobs.send(Job::Stop).ok();
228	        }
229	    }
230	}
231	
232	/// The checker threads: one session, each thread answering the requests of its queue in turn until it is stopped or
233	/// every sender is gone. The first thread creates the session and starts the others; the last to leave closes it.
234	fn serve(cwd: String, queues: Vec<mpsc::Receiver<Job>>, reads: Option<Arc<Reads>>) {
235	    let fs: Arc<dyn FS> = match reads {
236	        Some(reads) => Arc::new(bundled::wrap_fs(Recording { inner: osvfs::fs(), reads })),
237	        None => Arc::new(bundled::wrap_fs(osvfs::fs())),
238	    };
239	    let session = Session::new(SessionOptions::new(cwd, bundled::lib_path(), fs, false));
240	    let left = Arc::new(AtomicUsize::new(queues.len()));
241	    let mut queues = queues.into_iter();
242	    let Some(own) = queues.next() else { return session.close() };
243	    for (index, queue) in queues.enumerate() {
244	        let (session, still) = (session.clone(), left.clone());
245	        let spawned = std::thread::Builder::new()
246	            .name(format!("caliper-checker-{}", index + 1))
247	            .stack_size(CHECKER_STACK_BYTES)
248	            .spawn(move || answer(&session, queue, &still));
249	        // Its queue is dropped with the closure, so its lane's requests fail as from a stopped checker.
250	        if spawned.is_err() {
251	            left.fetch_sub(1, Ordering::AcqRel);
252	        }
253	    }
254	    answer(&session, own, &left);
255	}
256	
257	/// One checker thread: the requests of `queue` in turn, until it is stopped or every sender is gone. The last thread
258	/// of the session (`left`) closes it.
259	fn answer(session: &Session, queue: mpsc::Receiver<Job>, left: &AtomicUsize) {
260	    for job in queue {
261	        let asked = match job {
262	            Job::Request(asked) => asked,
263	            Job::Stop => break,
264	        };
265	        // A caller that stopped waiting (its deadline passed, its run ended) is not answered.
266	        if asked.reply.is_closed() {
267	            continue;
268	        }
269	        let answer = match session.handle_request(&asked.method, &asked.params) {
270	            Ok(Response::Json(text)) => Ok(text),
271	            Ok(Response::Binary(_)) => Err(format!("{} answered in binary, not JSON", asked.method)),
272	            Err(error) => Err(error.to_string()),
273	        };
274	        asked.reply.send(answer).ok();
275	    }
276	    if left.fetch_sub(1, Ordering::AcqRel) == 1 {
277	        session.close();
278	    }
279	}
280	
281	#[cfg(test)]
282	mod tests {
283	    #![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]
284	
285	    use serde_json::json;
286	
287	    use super::*;
288	
289	    fn runtime() -> tokio::runtime::Runtime {
290	        tokio::runtime::Builder::new_current_thread().enable_all().build().unwrap()
291	    }
292	
293	    fn linked() -> Backend {
294	        Backend::InProcess(InProcess::start(Utf8Path::new("/"), 1, None).unwrap())
295	    }
296	
297	    async fn ask(client: &Client, method: &str, params: Value) -> Result<Value, TscClientError> {
298	        let answer = client.request_raw(method, params, Duration::from_secs(120)).await?;
299	        Ok(serde_json::from_str(&answer).unwrap())
300	    }
301	
302	    /// A program of `file` holding `text`, held in the checker's memory: its snapshot and project.
303	    async fn program(client: &Client, file: &str, text: &str, resolution: u32) -> Result<Value, TscClientError> {
304	        let options =
305	            json!({ "strict": true, "noEmit": true, "target": 9, "module": 99, "moduleResolution": resolution });
306	        let created = ask(
307	            client,
308	            "createSnapshot",
309	            json!({
310	                "fileSystem": { "kind": "layer", "files": { file: text } },
311	                "createPrograms": [{ "rootFiles": [file], "compilerOptions": options }],
312	            }),
313	        )
314	        .await?;
315	        Ok(json!({ "snapshot": created["snapshot"], "project": created["projects"][0]["id"] }))
316	    }
317	
318	    /// `Deep` nested `depth` levels (`{ a: { a: ... string ... } }`), printed in full by the checker.
319	    async fn printed_deep(client: &Client, depth: usize) -> String {
320	        let file = "/virtual/deep.ts";
321	        let text = format!("export type Deep = {}string{};\n", "{ a: ".repeat(depth), " }".repeat(depth));
322	        let scope = program(client, file, &text, 100).await.unwrap();
323	        let with = |extra: Value| {
324	            let mut params = scope.clone();
325	            params.as_object_mut().unwrap().extend(extra.as_object().unwrap().clone());
326	            params
327	        };
328	        let module = ask(client, "getSymbolOfSourceFile", with(json!({ "file": file }))).await.unwrap();
329	        let exports = ask(client, "getExportsOfModule", with(json!({ "symbol": module["reference"] }))).await.unwrap();
330	        let deep = exports.as_array().unwrap().iter().find(|export| export["name"] == "Deep").unwrap();
331	        let declared =
332	            ask(client, "getDeclaredTypeOfSymbol", with(json!({ "symbol": deep["reference"] }))).await.unwrap();
333	        let flags = crate::rpc::flag::PRINT_EXPANDED;
334	        let printed =
335	            ask(client, "typeToString", with(json!({ "type": declared["id"], "flags": flags }))).await.unwrap();
336	        printed.as_str().unwrap().to_string()
337	    }
338	
339	    fn expected_deep(depth: usize) -> String {
340	        format!("{}string{}", "{ a: ".repeat(depth), "; }".repeat(depth))
341	    }
342	
343	    #[test]
344	    fn no_tsc_path_starts_the_linked_checker_and_an_explicit_one_is_checked_for_a_process() {
345	        let runtime = runtime();
346	        let start = |tsc_path: Option<&'static str>| Start {
347	            project_root: Utf8Path::new("/"),
348	            tsc_path: tsc_path.map(Utf8Path::new),
349	            expected_versions: &["7.1"],
350	            timeout: Duration::from_secs(5),
351	            extra_env: &[],
352	            threads: 1,
353	            reads: None,
354	        };
355	
356	        let linked = runtime.block_on(Backend::start(start(None))).unwrap();
357	        let missing = runtime.block_on(Backend::start(start(Some("/nowhere/tsc"))));
358	
359	        assert!(matches!(linked, Backend::InProcess(_)));
360	        assert_eq!(linked.process_id(), None);
361	        assert_eq!(missing.err(), locate::explicit_tsc(Utf8Path::new("/nowhere/tsc")).err());
362	        runtime.block_on(linked.shutdown());
363	    }
364	
365	    #[test]
366	    fn a_panic_inside_the_checker_is_an_error_to_that_request_and_the_session_keeps_answering() {
367	        let runtime = runtime();
368	        let checker = linked();
369	        let client = checker.client();
370	        let file = "/virtual/panic.ts";
371	        let text = "import x from \"./other\";\nexport const z = x;\n";
372	
373	        // A `moduleResolution` that names no kind reaches the resolver's panic, as it does in the Go checker.
374	        let panicked = runtime.block_on(program(&client, file, text, 12345));
375	        let after = runtime.block_on(program(&client, file, text, 100));
376	
377	        match panicked {
378	            Err(TscClientError::RpcError { code, message, data }) => {
379	                assert_eq!(code, INTERNAL_ERROR);
380	                assert_eq!(
381	                    message,
382	                    "api: client error: unsupported moduleResolution value 12345 (not a ModuleResolutionKind)"
383	                );
384	                assert_eq!(data, None);
385	            }
386	            other => panic!("expected the panic as an error, got {other:?}"),
387	        }
388	        let after = after.unwrap();
389	        assert!(after["snapshot"].as_u64().is_some() && after["project"].as_str().is_some(), "{after}");
390	        assert!(checker.is_alive());
391	        runtime.block_on(checker.shutdown());
392	    }
393	
394	    /// A type nested 2,000 deep overflows a default 2 MiB thread and aborts the process; the checker thread's stack
395	    /// holds it.
396	    #[test]
397	    fn a_type_nested_two_thousand_deep_is_printed_in_full() {
398	        let runtime = runtime();
399	        let checker = linked();
400	
401	        let printed = runtime.block_on(printed_deep(&checker.client(), 2_000));
402	
403	        assert_eq!(printed, expected_deep(2_000));
404	        runtime.block_on(checker.shutdown());
405	    }
406	
407	    /// Ten thousand deep takes about 3 s in a release build and far longer in a debug one:
408	    /// `cargo test --release -p caliper-docgen-semantic --lib checker -- --ignored`.
409	    #[test]
410	    #[ignore = "slow in a debug build; run in release"]
411	    fn a_type_nested_ten_thousand_deep_is_printed_in_full() {
412	        let runtime = runtime();
413	        let checker = linked();
414	
415	        let printed = runtime.block_on(printed_deep(&checker.client(), 10_000));
416	
417	        assert_eq!(printed, expected_deep(10_000));
418	        runtime.block_on(checker.shutdown());
419	    }
420	
421	    #[test]
422	    fn a_request_past_its_deadline_times_out_and_the_next_is_answered() {
423	        let runtime = runtime();
424	        let checker = linked();
425	        let client = checker.client();
426	        let text = format!("export type Deep = {}string{};\n", "{ a: ".repeat(500), " }".repeat(500));
427	        let params = json!({
428	            "fileSystem": { "kind": "layer", "files": { "/virtual/slow.ts": text } },
429	            "createPrograms": [{ "rootFiles": ["/virtual/slow.ts"], "compilerOptions": { "noEmit": true } }],
430	        });
431	
432	        let late = runtime.block_on(client.request_raw("createSnapshot", params, Duration::from_micros(1)));
433	        let next = runtime.block_on(program(&client, "/virtual/next.ts", "export const n = 1;\n", 100));
434	
435	        match late {
436	            Err(TscClientError::Timeout { method, after }) => {
437	                assert_eq!((method.as_str(), after), ("createSnapshot", Duration::from_micros(1)));
438	            }
439	            other => panic!("expected a timeout, got {other:?}"),
440	        }
441	        assert!(next.unwrap()["snapshot"].as_u64().is_some());
442	        runtime.block_on(checker.shutdown());
443	    }
444	
445	    #[test]
446	    fn a_stopped_checker_answers_every_later_request_as_closed() {
447	        let runtime = runtime();
448	        let checker = linked();
449	        let client = checker.client();
450	
451	        runtime.block_on(checker.shutdown());
452	        let after = runtime.block_on(client.request_raw("initialize", Value::Null, Duration::from_secs(5)));
453	
454	        assert!(matches!(after, Err(TscClientError::SessionClosed)), "{after:?}");
