104	    /// A tsconfig whose compiler options the checker uses (read with `parseConfigFile`); with none, a default set.
105	    pub tsconfig: Option<Utf8PathBuf>,
106	    /// A checker binary to run as a `tsc --api` process (`typescript@7.1`'s `tsc`, or `tsrs`) instead of the built-in
107	    /// checker.
108	    pub tsc_path: Option<Utf8PathBuf>,
109	    /// The components to ask about.
110	    pub targets: Vec<Target>,
111	    /// Bound on each request, and on a checker process's start-up handshake.
112	    pub request_timeout: Duration,
113	    /// The versions a checker binary's `package.json` may declare; one that is not among them is a start-up failure.
114	    /// The built-in checker is pinned and not checked.
115	    pub expected_versions: &'static [&'static str],
116	    /// Write every request and its answer here as JSON, to refresh the replay fixture the tests use.
117	    pub record_to: Option<Utf8PathBuf>,
118	    /// Environment for a checker process; the tests use it to pick a replay scenario.
119	    pub extra_env: Vec<(String, String)>,
120	    /// Ask the checker about a component's props, and about the members of each type, last to first. The answer must
121	    /// not change: no id the checker hands out, and so no order of queries, may show in it. The tests set this.
122	    pub reverse_queries: bool,
123	}
