126	    /// A request for `targets` under `project_root`, with a 60 second timeout, the supported versions, and no
127	    /// tsconfig or explicit `tsc` path.
128	    pub fn new(project_root: Utf8PathBuf, targets: Vec<Target>) -> Self {
129	        Self {
130	            project_root,
131	            tsconfig: None,
132	            tsc_path: None,
133	            targets,
134	            request_timeout: Duration::from_secs(60),
135	            expected_versions: SUPPORTED_VERSIONS,
136	            record_to: None,
137	            extra_env: Vec::new(),
138	            reverse_queries: false,
139	        }
