143	/// Resolves the request's components with the checker. Blocks; builds its own runtime, so it must not be called from
144	/// inside one. The runtime has up to four threads: the built-in checker answers two programs at once, each on a thread
145	/// of its own, and while it does, the answers it gave the other files in flight are read and converted on these.
146	pub fn resolve(request: SemanticRequest) -> SemanticOutcome {
147	    resolve_noting(request, None)
148	}
149	
150	/// [`resolve`], with the answer kept in `cache_dir` for the next run over the same request: a run whose built-in
151	/// checker would read the disk exactly as the last one did gets the last one's answer without starting the checker.
152	/// Every question that checker asked of the file system (each file it read or looked for, each directory it listed,
153	/// the tsconfig and what it extends) is asked again first, and any different answer, a new file where it found none
154	/// included, discards the kept answer whole; so does another build of Caliper or of the pinned checker, and another
155	/// request. A request that names a checker binary (`tsc_path`) or records its calls is answered as [`resolve`] answers
156	/// it, and nothing is kept for it. The answer is the one [`resolve`] gives.
157	pub fn resolve_cached(request: SemanticRequest, cache_dir: &Utf8Path) -> SemanticOutcome {
158	    if request.tsc_path.is_some() || request.record_to.is_some() {
159	        return resolve(request);
160	    }
161	    let file = cache_dir.join(kept::FILE);
162	    let key = kept::request_key(&request);
163	    let started = std::time::Instant::now();
164	    if let Some(outcome) = kept::load(&file, key) {
165	        tracing::debug!(ms = started.elapsed().as_millis() as u64, "the checker's kept answer still holds");
166	        return outcome;
167	    }
168	    let reads = Arc::new(kept::Reads::default());
169	    let outcome = resolve_noting(request, Some(reads.clone()));
170	    kept::save(&file, key, &reads, &outcome);
171	    outcome
172	}
173	
174	fn resolve_noting(request: SemanticRequest, reads: Option<Arc<kept::Reads>>) -> SemanticOutcome {
175	    let threads = std::thread::available_parallelism().map_or(1, |count| count.get().min(CONVERTER_THREADS));
176	    let built = tokio::runtime::Builder::new_multi_thread().worker_threads(threads).enable_all().build();
177	    let runtime = match built {
178	        Ok(runtime) => runtime,
179	        Err(error) => return SemanticOutcome::unavailable(format!("could not start an async runtime: {error}")),
180	    };
181	    runtime.block_on(run_noting(request, None, reads))
182	}
