184	/// The exported targets by file, in first-seen order, and an outcome that already holds a fallback for each target
185	/// the checker cannot be asked about.
186	fn group_by_file(request: &SemanticRequest) -> (SemanticOutcome, FxHashMap<&Utf8Path, Vec<&Target>>, Vec<&Utf8Path>) {
187	    let mut outcome = SemanticOutcome::default();
188	    let mut by_file: FxHashMap<&Utf8Path, Vec<&Target>> = FxHashMap::default();
189	    let mut order: Vec<&Utf8Path> = Vec::new();
190	    for target in &request.targets {
191	        if target.exports.is_empty() {
192	            outcome.fallbacks.push(fallback_of(target, "not exported by its module"));
193	            continue;
194	        }
195	        let group = by_file.entry(target.file_path.as_path()).or_default();
196	        if group.is_empty() {
197	            order.push(target.file_path.as_path());
198	        }
199	        group.push(target);
200	    }
201	    (outcome, by_file, order)
202	}
