227	/// Answers `request` with a checker started for it, asking `programs` programs at once, or by default as many as
228	/// [`CHECKER_PROGRAMS`] and the files allow ([`MIN_FILES_PER_PROGRAM`]).
229	#[cfg(test)]
230	async fn run(request: SemanticRequest, programs: Option<usize>) -> SemanticOutcome {
231	    run_noting(request, programs, None).await
232	}
233	
234	/// [`run`], the linked checker noting what it reads in `reads` ([`kept`]).
235	async fn run_noting(
236	    request: SemanticRequest,
237	    programs: Option<usize>,
238	    reads: Option<Arc<kept::Reads>>,
239	) -> SemanticOutcome {
240	    if request.targets.iter().all(|target| target.exports.is_empty()) {
241	        return group_by_file(&request).0;
242	    }
243	    let files = group_by_file(&request).2.len();
244	    let programs = programs.unwrap_or_else(|| CHECKER_PROGRAMS.min(files.div_ceil(MIN_FILES_PER_PROGRAM))).max(1);
245	    let checker = match start_noting(&request, programs, reads).await {
246	        Ok(checker) => checker,
247	        Err(reason) => return SemanticOutcome::unavailable(reason),
248	    };
249	    let outcome = answer_with(&checker, &request).await;
250	    checker.shutdown().await;
251	    outcome
252	}
