259	/// Answers the request's targets with a checker that is already running: one snapshot of as many programs rooted at
260	/// their files as the checker answers at once ([`Backend::parallel_programs`]), released once they are answered.
261	async fn answer_with(checker: &Backend, request: &SemanticRequest) -> SemanticOutcome {
262	    let files = root_files(request);
263	    if files.is_empty() {
264	        return group_by_file(request).0;
265	    }
266	    let started = std::time::Instant::now();
267	    let tsconfig = request.tsconfig.as_ref().map(|path| path.as_str());
268	    let count = checker.parallel_programs();
269	    let record = request.record_to.is_some();
270	    let opened = Rpc::open_programs(checker.client(), request.request_timeout, tsconfig, &files, record, count).await;
271	    let programs: Vec<Arc<Rpc>> = match opened {
272	        Ok(programs) => programs.into_iter().map(Arc::new).collect(),
273	        Err(error) => return SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")),
274	    };
275	    tracing::debug!(program_ms = started.elapsed().as_millis() as u64, programs = count, "semantic program built");
276	    let answered = answer_on(&programs, request, &files).await;
277	    if let Some(first) = programs.first() {
278	        first.release().await;
279	    }
280	    answered.unwrap_or_else(|error| SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")))
281	}
