283	/// Answers the request's targets on a snapshot whose programs are each rooted at `files` ([`root_files`]), one session
284	/// bound to each: a file is answered by one of them, the `n`th file by the `n % programs.len()`th. Each program has its
285	/// checker and its handles, so each has its own [`Converter`]; since every program holds the same files, each answers
286	/// a component as any other would, and the output does not depend on how the files are shared out. The snapshot is
287	/// left as it is, for the caller to keep or release.
288	async fn answer_on(
289	    programs: &[Arc<Rpc>],
290	    request: &SemanticRequest,
291	    files: &[String],
292	) -> Result<SemanticOutcome, CallError> {
293	    let (mut outcome, by_file, order) = group_by_file(request);
294	    let mut answered = session(programs, request, files, &by_file, &order).await?;
295	    outcome.components.append(&mut answered.components);
296	    outcome.fallbacks.append(&mut answered.fallbacks);
297	    Ok(outcome)
298	}
299	
300	async fn session(
301	    programs: &[Arc<Rpc>],
302	    request: &SemanticRequest,
303	    files: &[String],
304	    by_file: &FxHashMap<&Utf8Path, Vec<&Target>>,
305	    order: &[&Utf8Path],
306	) -> Result<SemanticOutcome, CallError> {
307	    let started = std::time::Instant::now();
308	    let Some(rpc) = programs.first() else { return Ok(SemanticOutcome::default()) };
309	    let converters: Vec<Converter> =
310	        programs.iter().map(|program| Converter::new(program.clone(), request.reverse_queries)).collect();
311	    let interner = Arc::new(PropInterner::default());
312	    // The files in order; each worker takes the next one when it is done with its last, so a program whose files take
313	    // longer answers fewer of them.
314	    let queue: VecDeque<Vec<Target>> = order
315	        .iter()
316	        .map(|file| by_file.get(file).into_iter().flatten().map(|target| (*target).clone()).collect())
317	        .collect();
318	    let queue = Arc::new(Mutex::new(queue));
319	
320	    let mut tasks = JoinSet::new();
321	    for worker in 0..FILES_IN_FLIGHT {
322	        let lane = worker % programs.len();
323	        let (Some(rpc), Some(converter)) = (programs.get(lane), converters.get(lane)) else { continue };
324	        let (rpc, converter, queue, interner) = (rpc.clone(), converter.clone(), queue.clone(), interner.clone());
325	        tasks.spawn(async move {
326	            let mut answered = (SemanticOutcome::default(), Vec::new());
327	            loop {
328	                let next = queue.lock().unwrap_or_else(std::sync::PoisonError::into_inner).pop_front();
329	                let Some(targets) = next else { return Ok(answered) };
330	                let (mut outcome, mut generic) = answer_file(&rpc, &converter, &interner, targets).await?;
331	                answered.0.components.append(&mut outcome.components);
332	                answered.0.fallbacks.append(&mut outcome.fallbacks);
333	                answered.1.append(&mut generic);
334	            }
335	        });
336	    }
337	
338	    let mut outcome = SemanticOutcome::default();
339	    let mut generic = Vec::new();
340	    let mut failure = None;
341	    while let Some(joined) = tasks.join_next().await {
342	        match joined {
343	            Ok(Ok((mut answered, mut instantiations))) => {
344	                outcome.components.append(&mut answered.components);
345	                outcome.fallbacks.append(&mut answered.fallbacks);
346	                generic.append(&mut instantiations);
347	            }
348	            Ok(Err(error)) => {
349	                failure = Some(error);
350	                tasks.abort_all();
351	            }
352	            // A panic inside a worker must not silently leave its components structural.
353	            Err(joined) if joined.is_panic() => {
354	                failure = Some(CallError::Fatal("a worker panicked".to_string()));
355	                tasks.abort_all();
356	            }
357	            // A cancelled task is one this loop aborted after a failure.
358	            Err(_cancelled) => {}
359	        }
360	    }
361	    if let Some(error) = failure {
362	        return Err(error);
363	    }
364	    if !generic.is_empty() {
365	        let mut instantiated =
366	            instantiate::answer(rpc, files, &request.project_root, &interner, request.reverse_queries, generic).await?;
367	        outcome.components.append(&mut instantiated.components);
368	        outcome.fallbacks.append(&mut instantiated.fallbacks);
369	    }
370	
371	    if let (Some(path), Some(recording)) = (&request.record_to, rpc.recording())
372	        && let Ok(json) = serde_json::to_string_pretty(&recording)
373	        && let Err(error) = std::fs::write(path, json)
374	    {
375	        tracing::warn!("could not write the recording to {path}: {error}");
376	    }
377	    tracing::debug!(
378	        requests = ?rpc.calls(),
379	        files = files.len(),
380	        type_memo = ?converters.iter().map(Converter::memo_stats).fold((0, 0), |sum, (hits, misses)| (sum.0 + hits, sum.1 + misses)),
381	        total_ms = started.elapsed().as_millis() as u64,
382	        "semantic backend finished"
383	    );
384	    outcome.components.sort_by(|a, b| a.key.cmp(&b.key));
385	    outcome.fallbacks.sort_by(|a, b| a.key.cmp(&b.key));
386	    Ok(outcome)
387	}
