393	/// A fatal error aborts the run; a call the checker rejected only sends that component to its structural result. The
394	/// generic components come back apart, to be answered from their instantiations once every file is done.
395	async fn answer_file(
396	    rpc: &Rpc,
397	    converter: &Converter,
398	    interner: &PropInterner,
399	    targets: Vec<Target>,
400	) -> Result<(SemanticOutcome, Vec<(Target, Instantiation)>), CallError> {
401	    let mut outcome = SemanticOutcome::default();
402	    let mut generic = Vec::new();
403	    let Some(first) = targets.first() else { return Ok((outcome, generic)) };
404	    let module = match module_exports(rpc, first.file_path.as_str()).await {
405	        Ok(Some(module)) => module,
406	        Ok(None) | Err(CallError::Rejected(_)) => {
407	            outcome
408	                .fallbacks
409	                .extend(targets.iter().map(|target| fallback_of(target, "not part of the checker's program")));
410	            return Ok((outcome, generic));
411	        }
412	        Err(fatal) => return Err(fatal),
413	    };
414	
415	    for target in &targets {
416	        let requests = Arc::new(AtomicU64::new(0));
417	        let started = std::time::Instant::now();
418	        let answered =
419	            REQUESTS.scope(requests.clone(), component::props_of(rpc, converter, interner, &module, target)).await;
420	        tracing::debug!(
421	            component = %target.display_name,
422	            requests = requests.load(Ordering::Relaxed),
423	            ms = started.elapsed().as_millis() as u64,
424	            "semantic component answered"
425	        );
426	        match answered {
427	            Ok(Answer::Props(component::Props { props, composes })) => {
428	                outcome.components.push(SemanticComponent { key: target.key.clone(), props, composes });
429	            }
430	            Ok(Answer::Fallback(reason)) => outcome.fallbacks.push(fallback_of(target, &reason)),
431	            Ok(Answer::Instantiate(instantiation)) => generic.push((target.clone(), instantiation)),
432	            Err(CallError::Rejected(message)) => {
433	                outcome.fallbacks.push(fallback_of(target, &format!("the checker rejected a request: {message}")));
434	            }
435	            Err(fatal) => return Err(fatal),
436	        }
437	    }
438	    Ok((outcome, generic))
439	}
