441	/// The module `file` is, as the checker reads it, with its exports; `None` when the file is not in its program.
442	async fn module_exports(rpc: &Rpc, file: &str) -> Result<Option<component::Module>, CallError> {
443	    let Some(symbol) = rpc.source_file_symbol(file).await? else { return Ok(None) };
444	    let exports = rpc.exports_of_module(&symbol.reference).await?;
445	    Ok(Some(component::Module { symbol, exports }))
446	}
