556	    async fn call(&self, method: &str, params: Value) -> Result<Box<str>, CallError> {
557	        if let Ok(mut calls) = self.calls.lock() {
558	            *calls.entry(method.to_string()).or_default() += 1;
559	        }
560	        REQUESTS.try_with(|count| count.fetch_add(1, std::sync::atomic::Ordering::Relaxed)).ok();
561	        let Some(log) = &self.recording else {
562	            return self.client.request_raw(method, params, self.deadline).await.map_err(classify);
563	        };
564	        let answer = self.client.request_raw(method, params.clone(), self.deadline).await.map_err(classify)?;
565	        let result: Value = decode(&answer)?;
566	        if let Ok(mut log) = log.lock() {
567	            log.push(json!({ "method": method, "params": params, "result": result }));
568	        }
569	        Ok(answer)
570	    }
