661	    /// Several requests in one round trip. A request the checker rejects fails the batch: nothing here asks for one
662	    /// that may legitimately fail.
663	    pub(crate) async fn batch(&self, requests: Vec<(&str, Value)>) -> Result<Vec<Box<str>>, CallError> {
664	        let wanted = requests.len();
665	        let scoped: Vec<Value> = requests
666	            .into_iter()
667	            .map(|(method, mut params)| {
668	                if let Value::Object(map) = &mut params {
669	                    map.insert("snapshot".to_string(), json!(self.snapshot));
670	                    map.insert("project".to_string(), json!(self.project));
671	                }
672	                json!({ "method": method, "params": params })
673	            })
674	            .collect();
675	        let mut answers = Vec::with_capacity(wanted);
676	        let mut token: Option<String> = None;
677	        loop {
678	            let mut params = json!({ "requests": scoped });
679	            if let (Some(token), Some(map)) = (&token, params.as_object_mut()) {
680	                map.insert("continuationToken".to_string(), json!(token));
681	            }
682	            let page: BatchPage = decode(&self.call("batchRequests", params).await?)?;
683	            for response in page.responses {
684	                if let Some(error) = response.error {
685	                    return Err(CallError::Rejected(error));
686	                }
687	                answers.push(response.result.map_or_else(|| Box::from("null"), Box::from));
688	            }
689	            match page.continuation_token {
690	                Some(next) => token = Some(next),
691	                None => break,
692	            }
693	        }
694	        if answers.len() != wanted {
695	            return Err(CallError::Rejected(format!("a batch of {wanted} requests got {} answers", answers.len())));
696	        }
697	        Ok(answers)
698	    }
