5	use crate::config::{BuildOptionsArgs, build_options};
6	use crate::output::{print_diagnostics, print_summary, write_atomic};
7	
8	/// Returns the process exit code (0 = success, 2 = extraction reported an
9	/// error-severity diagnostic) rather than calling `std::process::exit`
10	/// directly — keeps the exit decision testable and lets `main()` be the only
11	/// place that actually terminates the process.
12	pub fn cmd_extract(args: crate::ExtractArgs, quiet: bool, config_path: Option<&str>) -> Result<i32> {
13	    use indicatif::{ProgressBar, ProgressStyle};
14	
15	    let html_attributes = args.html_attributes.map(|m| match m {
16	        crate::HtmlAttributeModeArg::Curated => "curated",
17	        crate::HtmlAttributeModeArg::Full => "full",
18	        crate::HtmlAttributeModeArg::None => "none",
19	    });
20	    let options = build_options(BuildOptionsArgs {
21	        src: &args.src,
22	        cache_dir: args.cache_dir.as_deref(),
23	        no_cache: args.no_cache,
24	        html_attributes,
25	        config_path,
26	        extra_builtins: &args.extra_builtins,
27	        load_dependencies: args.load_dependencies,
28	        no_load_dependencies: args.no_load_dependencies,
29	        collapse_inherited_props: args.collapse_inherited_props.map(Into::into),
30	    })?;
31	    let mut options = options;
32	    if args.no_checker {
33	        options.checker = false;
34	    }
35	    if let Some(path) = &args.tsc_path {
36	        options.semantic_tsc_path = Some(path.into());
37	    }
38	
39	    let pb = if !quiet && !args.json {
40	        let pb = ProgressBar::new_spinner();
41	        pb.set_style(ProgressStyle::default_spinner().template("{spinner:.cyan} {msg}").into_diagnostic()?);
42	        pb.set_message("Extracting...");
43	        pb.enable_steady_tick(std::time::Duration::from_millis(80));
44	        Some(pb)
45	    } else {
46	        None
47	    };
48	
49	    let mut output = caliper_docgen_core::pipeline::extract(&options);
50	    if options.checker {
51	        let resolver = match args.no_resolver_facts {
52	            true => caliper_docgen_core::types::semantic::ResolverFacts::Off,
53	            false => caliper_docgen_core::types::semantic::ResolverFacts::Used,
54	        };
55	        let timeout = std::time::Duration::from_millis(args.semantic_timeout_ms);
56	        apply_semantic_backend(&options, timeout, resolver, None, true, &mut output);
57	    }
58	
59	    if let Some(pb) = pb {
60	        pb.finish_and_clear();
61	    }
62	
63	    // --json ignores --out/--format — see ExtractArgs::json's doc comment.
64	    if args.json {
65	        let mut stdout = std::io::BufWriter::with_capacity(1 << 16, std::io::stdout().lock());
66	        caliper_docgen_core::pipeline::write_extraction_output_json(&output, &mut stdout).into_diagnostic()?;
67	        writeln!(stdout).and_then(|()| stdout.flush()).into_diagnostic()?;
68	    } else {
69	        if !quiet {
70	            print_summary(&output, quiet);
71	            print_diagnostics(&output.diagnostics);
72	        }
