"""CPU-weighted summary of a samply profile (weights = threadCPUDelta, so parked samples count 0).
Usage: cpu.py <profile.json.gz> <thread-regex> [N] [mode] ; mode: self|incl|both|timeline|callers:<substr>
Threads matching the regex are merged."""
import bisect
import gzip
import json
import re
import sys
from collections import Counter, defaultdict

path, want = sys.argv[1], re.compile(sys.argv[2])
N = int(sys.argv[3]) if len(sys.argv) > 3 else 40
mode = sys.argv[4] if len(sys.argv) > 4 else 'both'
p = json.load(gzip.open(path))
syms = json.load(open(path.replace('.json.gz', '.json.syms.json')))
strings = syms['string_table']
libmap = {e['code_id']: sorted(e['symbol_table'], key=lambda x: x['rva']) for e in syms['data']}
starts = {c: [e['rva'] for e in t] for c, t in libmap.items()}
libs = p['libs']
import os
TMIN = float(os.environ.get('TMIN', '0'))
TMAX = float(os.environ.get('TMAX', '1e12'))


def name_of(li, addr):
    lib = libs[li]
    t = libmap.get(lib.get('codeId'))
    if not t:
        return lib['name'] + '?'
    i = bisect.bisect_right(starts[lib['codeId']], addr) - 1
    return strings[t[i]['symbol']] if i >= 0 else lib['name'] + '?'


def short(n):
    for _ in range(4):
        n = re.sub(r'<[^<>]*>', '', n)
    n = re.sub(r'::h[0-9a-f]{16}$', '', n)
    return n[:160]


selfc, inclc, callers = Counter(), Counter(), Counter()
total = 0.0
timeline = defaultdict(float)
t0 = min(t['samples']['time'][0] for t in p['threads'] if t['samples']['length'])
for th in p['threads']:
    if not want.search(th['name']):
        continue
    ft, st = th['frameTable'], th['stackTable']
    names = []
    for i in range(ft['length']):
        res = th['funcTable']['resource'][ft['func'][i]]
        lib = th['resourceTable']['lib'][res] if res is not None and res >= 0 else None
        names.append('?' if lib is None else short(name_of(lib, ft['address'][i])))
    s = th['samples']
    for k, stack in enumerate(s['stack']):
        w = (s['threadCPUDelta'][k] or 0) / 1000.0  # ms
        if stack is None or w <= 0:
            continue
        if not (TMIN <= s['time'][k] - t0 < TMAX):
            continue
        total += w
        timeline[int((s['time'][k] - t0) // BUCKET)] += w
        seen, first, chain = set(), True, []
        while stack is not None:
            n = names[st['frame'][stack]]
            chain.append(n)
            if first:
                selfc[n] += w
                first = False
            if n not in seen:
                inclc[n] += w
                seen.add(n)
            stack = st['prefix'][stack]
        if mode.startswith('callers:'):
            needle = mode.split(':', 1)[1]
            for j, n in enumerate(chain):
                if needle in n:
                    callers[' <- '.join(chain[j:j + 4])] += w
                    break
print(f'total CPU ms {total:.0f}')
if mode == 'timeline':
    for b in sorted(timeline):
        print(f"{b*BUCKET:6.0f}ms"+f" {timeline[b]:7.1f}')
elif mode.startswith('callers:'):
    for n, c in callers.most_common(N):
        print(f'{c:8.1f} {100*c/total:5.1f}% {n}')
else:
    if mode in ('self', 'both'):
        print('-- self')
        for n, c in selfc.most_common(N):
            print(f'{c:8.1f} {100*c/total:5.1f}% {n}')
    if mode in ('incl', 'both'):
        print('-- inclusive')
        for n, c in inclc.most_common(N):
            print(f'{c:8.1f} {100*c/total:5.1f}% {n}')

