91	/// Shares identical props between components, as the structural resolver does: a design system's components repeat
92	/// the same few hundred props, and Chakra's 600 components would otherwise hold 470,000 copies.
93	#[derive(Debug, Default)]
94	pub struct PropInterner {
95	    by_hash: Mutex<FxHashMap<u64, Vec<Arc<SemanticProp>>>>,
96	}
97	
98	impl PropInterner {
99	    /// The one shared copy of `prop`: an equal prop interned earlier, or `prop` itself the first time. If the internal
100	    /// lock is poisoned it returns `prop` unshared rather than failing.
101	    pub fn share(&self, prop: SemanticProp) -> Arc<SemanticProp> {
102	        self.share_arc(Arc::new(prop))
103	    }
104	
105	    /// [`Self::share`] for a prop already behind an `Arc`, such as one another interner shared: the one copy equal to
106	    /// it, or `prop` itself the first time.
107	    pub fn share_arc(&self, prop: Arc<SemanticProp>) -> Arc<SemanticProp> {
108	        let hash = prop.structural_hash();
109	        let Ok(mut by_hash) = self.by_hash.lock() else { return prop };
110	        let bucket = by_hash.entry(hash).or_default();
111	        if let Some(existing) = bucket.iter().find(|existing| ***existing == *prop) {
112	            return existing.clone();
113	        }
114	        bucket.push(prop.clone());
115	        prop
116	    }
117	}
