543	fn replace_props<'a>(
544	    entry: &mut ComponentEntry,
545	    props_in: impl Iterator<Item = &'a Arc<SemanticProp>>,
546	    merge: &Merge<'_>,
547	    shared: &mut FxHashMap<u64, Vec<Arc<ParsedProp>>>,
548	    memo: &mut MergeMemo,
549	) -> MergedProps {
550	    let Merge { composes, unanswered, syntax, resolver } = *merge;
551	    let code_defaults = syntax.code_defaults(entry);
552	    let mut props: BTreeMap<String, Arc<ParsedProp>> = BTreeMap::new();
553	    let mut unread = 0;
554	    for prop in props_in {
555	        let structural = entry.props.get(&prop.name);
556	        let code_default = code_defaults.and_then(|defaults| defaults.get(&prop.name));
557	        // The union a prop with a `parent` writes is found by the prop alone, so it needs no place in the key; one with
558	        // none is looked for in the entry's own file.
559	        let written = prop.parent.is_none().then(|| syntax.written(entry, prop));
560	        let key: MergeKey = (
561	            Arc::as_ptr(prop) as usize,
562	            structural.map_or(0, |s| Arc::as_ptr(s) as usize),
563	            written.flatten().map_or((0, 0), |w| (w.as_ptr() as usize, w.len())),
564	            code_default.map_or(0, |d| std::ptr::from_ref(d) as usize),
565	        );
566	        if let Some(made) = memo.made.get(&key) {
567	            unread += usize::from(made.unread);
568	            props.insert(prop.name.clone(), made.merged.clone());
569	            continue;
570	        }
571	        let written = written.unwrap_or_else(|| syntax.written(entry, prop));
572	        let description = if prop.description.is_empty() {
573	            structural.map(|s| s.description.clone()).unwrap_or_default()
574	        } else {
575	            prop.description.clone()
576	        };
577	        let tags = if prop.tags.is_empty() {
578	            structural.map(|s| s.tags.clone()).unwrap_or_default()
579	        } else {
580	            prop.tags.clone()
581	        };
582	        let unread_kinds = structural.map(|s| unread_by_checker(&prop.prop_type, &s.prop_type)).unwrap_or_default();
583	        let prop_type = match structural {
584	            Some(structural) if !unread_kinds.is_empty() => structural.prop_type.clone(),
585	            Some(_) | None => declared_order(prop.prop_type.clone(), written, structural.map(|s| &**s), resolver),
586	        };
587	        unread += usize::from(!unread_kinds.is_empty());
588	        let merged = ParsedProp::new(
589	            prop.name.clone(),
590	            prop_type,
591	            prop.required,
592	            default_of(code_default, &prop.tags, structural.map(|s| &**s), resolver),
593	            description,
594	            tags,
595	            prop.parent.clone(),
596	            prop.declarations.clone(),
597	        )
598	        .degraded_also_by(&unread_kinds);
599	        let mut hasher = FxHasher::default();
600	        merged.structural_hash(&mut hasher);
601	        let bucket = shared.entry(hasher.finish()).or_default();
602	        let merged = match bucket.iter().find(|existing| ***existing == merged) {
603	            Some(existing) => existing.clone(),
604	            None => {
605	                let merged = Arc::new(merged);
606	                bucket.push(merged.clone());
607	                merged
608	            }
609	        };
610	        memo.made.insert(
611	            key,
612	            MemoEntry {
613	                _semantic: prop.clone(),
614	                _structural: structural.cloned(),
615	                merged: merged.clone(),
616	                unread: !unread_kinds.is_empty(),
617	            },
618	        );
619	        props.insert(prop.name.clone(), merged);
620	    }
621	    let mut kept = 0;
622	    if unanswered == Unanswered::Keep {
623	        for (name, structural) in &entry.props {
624	            if !props.contains_key(name) {
625	                props.insert(name.clone(), structural.clone());
626	                kept += 1;
627	            }
628	        }
629	    }
630	    entry.props = props;
631	    if let Some(composes) = composes {
632	        entry.composes = composes.to_vec();
633	    }
634	    MergedProps { kept, unread, diagnostics: Vec::new() }
