        LIVE.fetch_sub(layout.size() as u64, Relaxed);
        self.note(new_size);
        p
    }
}

impl Counting {
    fn note(&self, size: usize) {
        let live = LIVE.fetch_add(size as u64, Relaxed) + size as u64;
        PEAK.fetch_max(live, Relaxed);
        if GUARD.with(|g| g.get()) {
            return;
        }
        GUARD.with(|g| g.set(true));
        let k = kind();
        COUNT[k as usize].fetch_add(1, Relaxed);
        BYTES[k as usize].fetch_add(size as u64, Relaxed);
        let n = SEQ.fetch_add(1, Relaxed);
        if n % every() == 0 {
            let mut ips = Vec::with_capacity(48);
            unsafe {
                backtrace::trace_unsynchronized(|frame| {
                    ips.push(frame.ip() as usize);
                    ips.len() < 48
                });
            }
            if let Ok(mut s) = SAMPLES.lock() {
                s.push((k, size, ips));
            }
        }
        GUARD.with(|g| g.set(false));
    }
}

pub fn snapshot() -> (u64, u64, u64, u64) {
    let c: u64 = COUNT.iter().map(|a| a.load(Relaxed)).sum();
    let b: u64 = BYTES.iter().map(|a| a.load(Relaxed)).sum();
    (c, b, LIVE.load(Relaxed), PEAK.load(Relaxed))
}

/// Phase mark on stderr: elapsed ms since start, allocation count/bytes since last mark, live and peak.
pub fn mark(label: &str) {
    use std::sync::OnceLock;
    static START: OnceLock<std::time::Instant> = OnceLock::new();
    static LAST: Mutex<(u64, u64)> = Mutex::new((0, 0));
    if std::env::var_os("PHASES").is_none() {
        return;
    }
    let start = START.get_or_init(std::time::Instant::now);
    let (c, b, live, peak) = snapshot();
    let mut last = LAST.lock().unwrap();
    eprintln!(
        "PHASE {:>8.1}ms {:<40} allocs+{:>10} bytes+{:>8.1}MiB live={:>7.1}MiB peak={:>7.1}MiB",
        start.elapsed().as_secs_f64() * 1e3,
        label,
        c - last.0,
        (b - last.1) as f64 / 1048576.0,
        live as f64 / 1048576.0,
        peak as f64 / 1048576.0
    );
    *last = (c, b);
}

pub fn report() {
    if std::env::var_os("ALLOC_REPORT").is_none() {
        return;
    }
    let names = ["main", "checker", "tokio", "rayon", "other", "unknown"];
    for k in 0..KINDS {
        eprintln!(
            "ALLOC kind={:<8} count={:>11} bytes={:>9.1}MiB",
            names[k],
            COUNT[k].load(Relaxed),
            BYTES[k].load(Relaxed) as f64 / 1048576.0
        );
    }
    GUARD.with(|g| g.set(true));
    let samples = std::mem::take(&mut *SAMPLES.lock().unwrap());
    let e = every() as u64;
    // site = first frame that is not allocator/alloc/core/std/serde/hashbrown, plus its caller.
    let mut cache: std::collections::HashMap<usize, String> = std::collections::HashMap::new();
    let mut by_site: std::collections::HashMap<(u8, String), (u64, u64)> = std::collections::HashMap::new();
    let skip = |n: &str| {
        n.starts_with("alloc::")
            || n.starts_with("<alloc::")
            || n.starts_with("core::")
            || n.starts_with("<core::")
            || n.starts_with("std::")
            || n.starts_with("<std::")
            || n.contains("allocprof")
            || n.starts_with("hashbrown")
            || n.starts_with("<hashbrown")
            || n.starts_with("serde_json::")
            || n.starts_with("<serde_json::")
            || n.starts_with("serde::")
            || n.starts_with("<serde::")
            || n.starts_with("__rust")
            || n.starts_with("mi_")
            || n.starts_with("_mi")
            || n.starts_with("backtrace::")
            || n.starts_with("indexmap")
            || n.starts_with("<indexmap")
            || n.starts_with("smallvec")
            || n.starts_with("<smallvec")
            || n.contains("::clone")
            || n.contains("Clone>::clone")
            || n.contains("FromIterator")
            || n.contains("from_iter")
            || n.contains("rustc_entry")
            || n == "?"
    };
    for (k, size, ips) in samples {
        let mut frames = Vec::new();
        for ip in ips.iter().skip(1) {
            let name = cache
                .entry(*ip)
                .or_insert_with(|| {
                    let mut out = String::from("?");
                    backtrace::resolve(*ip as *mut std::ffi::c_void, |sym| {
                        if out == "?" {
                            if let Some(n) = sym.name() {
                                let s = format!("{n:#}");
                                out = s;
                            }
                        }
                    });
                    out
                })
                .clone();
            frames.push(name);
        }
        let mut it = frames.iter().filter(|n| !skip(n));
        let a = it.next().cloned().unwrap_or_default();
        let b = it.next().cloned().unwrap_or_default();
        let site = format!("{a}  <-  {b}");
        let entry = by_site.entry((k, site)).or_default();
        entry.0 += e;
        entry.1 += size as u64 * e;
    }
    let mut rows: Vec<_> = by_site.into_iter().collect();
    rows.sort_by(|a, b| b.1.0.cmp(&a.1.0));
    for ((k, site), (c, b)) in rows.iter().take(60) {
        eprintln!("SITE {:<8} ~count={:>10} ~MiB={:>8.1} {}", names[*k as usize], c, *b as f64 / 1048576.0, site);
    }
    rows.sort_by(|a, b| b.1.1.cmp(&a.1.1));
    for ((k, site), (c, b)) in rows.iter().take(40) {
        eprintln!("SITEB {:<8} ~count={:>10} ~MiB={:>8.1} {}", names[*k as usize], c, *b as f64 / 1048576.0, site);
    }
}

